"""Compare native arithmetic with an independently constructed Circuit."""

import torch

import flagquantum as fq
from examples.synthesis.compare_states import compare_states
from examples.synthesis.functions.arithmetic.bitwise_invert.bitwise_invert_example.main import (
    main,
)
from flagquantum.synth import synthesize


def reference_circuit() -> fq.Circuit:
    return fq.Circuit(6, dtype=torch.complex128).x(0).x(1).x(5)


def run_example() -> None:
    compare_states(synthesize(main), reference_circuit(), ("x", "y"))


if __name__ == "__main__":
    run_example()
